interface LogRecord {
  level: string;
  message: string;
  timestamp: string;
  [key: string]: any;
}

interface Formatter {
  format(record: LogRecord): string;
}

class PlainFormatter implements Formatter {
  format(r: LogRecord) { return `${r.timestamp} [${r.level}] ${r.message}`; }
}

class JsonFormatter implements Formatter {
  format(r: LogRecord) { return JSON.stringify(r); }
